//! Phase 29 fuzz target for the Python signature parser and the C/C++ domain
//! declaration parser in `scribe-domains`.
//!
//! These parsers return semantic values rather than byte spans, so the
//! analogous invariants are:
//!   * no panic for any generated byte/Unicode string;
//!   * deterministic output for identical input;
//!   * structural consistency (a parsed name is the join of its segments,
//!     every emitted token is derived from the input);
//!   * bounded resource usage (the number of emitted tokens is linear in the
//!     input length and the generators cap input size).
//!
//! Default case count is 2048 per property; `PROPTEST_CASES` raises it for the
//! stress campaign.

use proptest::prelude::*;
use scribe_domains::{parse_annotation, parse_reftarget, parse_sig_re, Inventory};
use scribe_domains::cpp::parser::{parse_cpp_declaration, parse_cpp_xref, CppDecl};
use scribe_domains::python::signature::ParsedSig;

fn fuzz_cases() -> u32 {
    std::env::var("PROPTEST_CASES")
        .ok()
        .and_then(|value| value.parse::<u32>().ok())
        .filter(|&n| n > 0)
        .unwrap_or(2048)
}

fn signature_string() -> impl Strategy<Value = String> {
    let alphabet: Vec<char> = "abcXYZ_()[]{}<>:.,*&=+-/~| \t\n'\"0123456789中é"
        .chars()
        .collect();
    prop::collection::vec(prop::sample::select(alphabet), 0..120)
        .prop_map(|chars| chars.into_iter().collect())
}

fn cpp_string() -> impl Strategy<Value = String> {
    let alphabet: Vec<char> = "abcXYZ_()[]{}<>:.,*&=+-~| \t\n;0123456789中é"
        .chars()
        .collect();
    prop::collection::vec(prop::sample::select(alphabet), 0..120)
        .prop_map(|chars| chars.into_iter().collect())
}

fn assert_py_sig_invariants(input: &str, sig: &Option<ParsedSig>) {
    let Some(sig) = sig else { return };
    assert!(!sig.name.is_empty(), "parsed signature has empty name for {input:?}");
    if !sig.prefix.is_empty() {
        assert!(sig.prefix.ends_with('.'), "prefix must end in '.': {:?}", sig.prefix);
    }
    // The declared name must occur in the (trimmed) input; this is the
    // structural analogue of an in-bounds / ordered span.
    let trimmed = input.trim();
    assert!(
        trimmed.contains(&sig.name),
        "parsed name {:?} not present in input {input:?}",
        sig.name
    );
}

fn assert_cpp_invariants(decl: &CppDecl) {
    let joined = decl
        .segments
        .iter()
        .map(|segment| segment.text.as_str())
        .collect::<Vec<_>>()
        .join("::");
    assert_eq!(joined, decl.name, "CppDecl.name is not the join of its segments");
    let token_count = decl.prefix.len()
        + decl.params.iter().map(Vec::len).sum::<usize>()
        + decl.suffix.len()
        + decl.alias.as_ref().map_or(0, Vec::len);
    assert!(token_count <= 4096, "unbounded token output: {token_count}");
}

proptest! {
    #![proptest_config(ProptestConfig::with_cases(fuzz_cases()))]

    #[test]
    fn python_signature_never_panics(input in signature_string()) {
        let sig = parse_sig_re(&input);
        assert_py_sig_invariants(&input, &sig);
        prop_assert_eq!(sig, parse_sig_re(&input), "signature parse not deterministic");
    }

    #[test]
    fn python_annotation_never_panics(input in signature_string()) {
        let tokens = parse_annotation(&input);
        prop_assert!(
            tokens.len() <= input.chars().count() + 8,
            "annotation token count is not linear in input length"
        );
        prop_assert_eq!(tokens, parse_annotation(&input), "annotation parse not deterministic");
    }

    #[test]
    fn python_reftarget_never_panics(
        target in signature_string(),
        suppress in prop::bool::ANY,
    ) {
        let (reftype, normalized, title, specific) = parse_reftarget(&target, suppress);
        prop_assert!(!reftype.is_empty(), "empty reftype");
        // Modifiers may strip a prefix, but the normalized target must remain a
        // suffix of the input (structural containment, like a byte span).
        prop_assert!(
            target.contains(&normalized),
            "normalized target {normalized:?} not contained in {target:?}"
        );
        let _ = (title, specific);
    }

    #[test]
    fn cpp_declaration_never_panics(
        input in cpp_string(),
        objtype in prop::sample::select(vec!["function", "class", "member", "variable", "enum", "type"]),
        domain in prop::sample::select(vec!["cpp", "c"]),
    ) {
        let decl = parse_cpp_declaration(&input, objtype, domain);
        assert_cpp_invariants(&decl);
        prop_assert_eq!(
            decl,
            parse_cpp_declaration(&input, objtype, domain),
            "C++ declaration parse not deterministic"
        );
    }

    #[test]
    fn cpp_xref_never_panics(input in cpp_string()) {
        let xref = parse_cpp_xref(&input);
        prop_assert!(xref.len() <= input.len() + 8, "unbounded C++ xref output");
        prop_assert_eq!(xref, parse_cpp_xref(&input), "C++ xref parse not deterministic");
    }

    /// Intersphinx inventory parsing consumes untrusted bytes fetched from a
    /// remote server. Arbitrary byte strings (including invalid UTF-8, truncated
    /// v1/v2 headers and malformed zlib payloads) must never panic, and a
    /// successful parse must be deterministic (item count is bounded by the
    /// input length so a decompressed bomb cannot slip through silently).
    #[test]
    fn inventory_loads_never_panics(
        bytes in prop::collection::vec(any::<u8>(), 0..512),
    ) {
        let first = Inventory::loads(&bytes, "https://example.test/");
        let second = Inventory::loads(&bytes, "https://example.test/");
        prop_assert_eq!(
            first.as_ref().ok().map(Inventory::len),
            second.as_ref().ok().map(Inventory::len),
            "inventory parse not deterministic"
        );
        if let Ok(inventory) = first {
            prop_assert!(
                inventory.len() <= bytes.len(),
                "inventory item count exceeded input byte length"
            );
        }
    }
}

// ----- deterministic regressions -------------------------------------------

/// Adversarial corpus carried over from the Phase 12/13 domain tests. Every
/// input must parse without panicking; the well-formed ones must produce the
/// exact name/segments we assert so a later change cannot silently regress.
#[test]
fn regression_signature_and_declaration_corpus() {
    const PY_SIGS: &[&str] = &[
        "",
        "func()",
        "Class.method(self, arg: int = 1, *args, **kwargs) -> str",
        "func[T](x: list[T]) -> Optional[T]",
        "async  mod.func(a, /, b, *, c=1)",
        "f((((((((((((((((((((x))))))))))))))))))))",
        "unterminated(a, b",
        "中.函数(x) -> 类型",
        "f(a[1:2], {'k': 'v'}, \")\")",
    ];
    for sig in PY_SIGS {
        let parsed = parse_sig_re(sig);
        assert_py_sig_invariants(sig, &parsed);
        assert_eq!(parsed, parse_sig_re(sig));
        let _ = parse_annotation(sig);
        let _ = parse_reftarget(sig, false);
    }

    const CPP_DECLS: &[&str] = &[
        "",
        // Phase 29 fuzz finding: an alias with an empty declaration head used
        // to panic at `head[name_index]` (index 0 into an empty slice).
        "=aa",
        "=",
        "= a",
        "void f()",
        "float Sphinx::version",
        "template<typename T> T max(T a, T b)",
        "std::vector<int> ns::Class<T>::method(const int&) const",
        "operator<<",
        "A::B::~B()",
        "using X = std::vector<std::map<int, int>>",
        "((((((((((x))))))))))",
        "中文::函数(int)",
    ];
    for decl in CPP_DECLS {
        let parsed = parse_cpp_declaration(decl, "function", "cpp");
        assert_cpp_invariants(&parsed);
        let _ = parse_cpp_xref(decl);
    }
}
